import{_ as a,o as e,c as l,ag as d}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"EmakiSkills","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/index.md","filePath":"modules/skills/index.md","lastUpdated":null}'),i={name:"modules/skills/index.md"};function r(s,t,o,n,h,c){return e(),l("div",null,[...t[0]||(t[0]=[d(`<h1 id="emakiskills" tabindex="-1">EmakiSkills <a class="header-anchor" href="#emakiskills" aria-label="Permalink to &quot;EmakiSkills&quot;">​</a></h1><p>EmakiSkills 是玩家技能管理模块，负责技能解锁、主动技能槽位、被动触发器、施法模式、冷却、资源消耗、升级和玩家档案。技能实际效果通常由 MythicMobs 执行，EmakiSkills 负责“什么时候允许释放、消耗什么、谁触发”。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.6.4</code></td></tr><tr><td>主命令</td><td><code>/emakiskills</code></td></tr><tr><td>别名</td><td><code>/eskills</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>MythicMobs、EmakiAttribute、PlaceholderAPI、AuraSkills、MythicLib、MMOCore</td></tr><tr><td>主要权限</td><td><code>emakiskills.use</code>、<code>emakiskills.reload</code>、<code>emakiskills.admin</code>、<code>emakiskills.debug</code></td></tr></tbody></table><h2 id="模块分工" tabindex="-1">模块分工 <a class="header-anchor" href="#模块分工" aria-label="Permalink to &quot;模块分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块 / 插件</th><th>职责</th></tr></thead><tbody><tr><td>EmakiSkills</td><td>技能定义、槽位、触发器、冷却、资源、升级、玩家数据。</td></tr><tr><td>MythicMobs</td><td>执行真正的技能效果，例如伤害、粒子、召唤、位移。</td></tr><tr><td>EmakiAttribute</td><td>提供属性检查、资源检查和资源消耗。</td></tr><tr><td>EmakiItem</td><td>物品可提供技能解锁、触发器或套装技能。</td></tr><tr><td>PlaceholderAPI</td><td>展示技能状态、冷却、等级等信息。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiSkills/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>├── resources/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── skills_gui.yml</span></span>
<span class="line"><span>│   └── trigger_select_gui.yml</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>GUI、施法模式、等级管理、槽位清理和调试命令。</td></tr><tr><td><a href="./definitions.html">技能定义</a></td><td>主动/被动技能、资源消耗、升级和配置字段。</td></tr><tr><td><a href="./triggers.html">触发器</a></td><td>主动触发器、被动触发器、冲突和连击配置。</td></tr><tr><td><a href="./parameters.html">技能参数</a></td><td>等级参数、变量和运行时解析。</td></tr><tr><td><a href="./script.html">原生脚本系统</a></td><td>脚本模式、阶段、动作、限制和目标解析。</td></tr><tr><td><a href="./actionbar.html">技能状态栏</a></td><td>Action Bar 模板、刷新间隔和施法模式提示。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>技能释放、等级、槽位、冷却和手动解锁动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>技能 API 与脚本动作扩展。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>技能流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="技能类型" tabindex="-1">技能类型 <a class="header-anchor" href="#技能类型" aria-label="Permalink to &quot;技能类型&quot;">​</a></h2><h3 id="主动技能" tabindex="-1">主动技能 <a class="header-anchor" href="#主动技能" aria-label="Permalink to &quot;主动技能&quot;">​</a></h3><p>主动技能通常由玩家手动释放，例如通过技能槽、命令、GUI 或施法模式。主动技能常见配置：</p><ul><li>MythicMobs 技能 ID。</li><li>冷却时间。</li><li>全局冷却。</li><li>资源消耗。</li><li>条件检查。</li><li>技能等级和参数。</li></ul><h3 id="被动技能" tabindex="-1">被动技能 <a class="header-anchor" href="#被动技能" aria-label="Permalink to &quot;被动技能&quot;">​</a></h3><p>被动技能由事件触发，例如攻击、受击、击杀、移动、格挡等。被动技能需要配置触发器和冲突处理方式。</p><h2 id="施法模式" tabindex="-1">施法模式 <a class="header-anchor" href="#施法模式" aria-label="Permalink to &quot;施法模式&quot;">​</a></h2><p>施法模式用于让玩家在特定状态下选择或释放技能。当前服务端无法原生监听客户端 G 键这类本地按键，因此技能触发通常依赖服务端可见行为，例如命令、GUI、F 键交换手、交互事件等。</p><h2 id="资源系统" tabindex="-1">资源系统 <a class="header-anchor" href="#资源系统" aria-label="Permalink to &quot;资源系统&quot;">​</a></h2><p>技能可以消耗或检查多种资源：</p><ul><li><code>ea-resource</code>：通过 EmakiAttribute Bridge 消耗 Attribute 资源。</li><li><code>attribute-check</code>：检查某个属性是否达到要求。别名 <code>ea-attribute-check</code>。</li><li><code>local-resource</code>：使用 EmakiSkills 本地资源定义。</li><li><code>auraskills-mana</code>：使用 AuraSkills 的法力值。别名 <code>aura-skills-mana</code>、<code>aura-mana</code>。</li><li><code>mythiclib-mana</code>：使用 MythicLib / MMOCore 的法力值。别名 <code>mmocore-mana</code>、<code>mythic-mana</code>。</li></ul><h2 id="典型释放流程" tabindex="-1">典型释放流程 <a class="header-anchor" href="#典型释放流程" aria-label="Permalink to &quot;典型释放流程&quot;">​</a></h2><ol><li>玩家触发主动或被动技能。</li><li>Skills 检查玩家是否拥有该技能。</li><li>检查技能等级、槽位、触发器和条件。</li><li>检查冷却和全局冷却。</li><li>检查并消耗资源。</li><li>调用 MythicMobs 技能。</li><li>写入冷却、统计或升级进度。</li><li>向玩家发送反馈。</li></ol>`,23)])])}const k=a(i,[["render",r]]);export{p as __pageData,k as default};
